{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": ["C16", "C13", "C05", "C08", "C09", "C12", "C07", "C47", "C54", "C57"],
  "contradictory_card_ids": ["C50", "C52", "C51", "C56", "C58", "C25"],
  "prediction_basis_card_ids": ["C16", "C13", "C05", "C08", "C09", "C12", "C07"],
  "claims": [
    {
      "claim": "Direct human nucleoside-analog bioavailability records in the gold contexts are at or above the 20% threshold: zalcitabine absolute F ≈80% (range 54–127%) in fasted patients and 70–90% in broader studies; didanosine fasted F was 22–29%; zidovudine F was 0.61 in patients with cirrhosis.",
      "card_ids": ["C16", "C13", "C05", "C08", "C09", "C12", "C07"]
    },
    {
      "claim": "L4 records show high solubility for ribavirin, a close carboxamide-riboside analog, but very low Caco-2 permeability for ribavirin and levovirin; this is an absorption concern, not a direct F<20% outcome, and the ribavirin Caco-2 result is explicitly linked to limited hCNT2 expression in the assay.",
      "card_ids": ["C47", "C54", "C57", "C50", "C52"]
    },
    {
      "claim": "The only sub-20% direct F record among the nucleoside contexts is gemcitabine in mice (10%), an L2 nonvoting record from a different compound and species; it is insufficient to overturn the human nucleoside F records.",
      "card_ids": ["C25"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C47", "C50", "C51", "C52", "C54", "C56", "C57", "C58"]
    }
  ],
  "evidence_gaps": [
    "No AICAR-specific absolute oral bioavailability or systemic exposure measurement is supplied.",
    "No AICAR-specific intestinal permeability, transporter, or first-pass metabolism data are supplied.",
    "L4 permeability data are from analogs (ribavirin, levovirin, gemcitabine) and Caco-2/PAMPA assays, not from human F measurements.",
    "No formulation, dose, prandial state, or species context for AICAR is supplied.",
    "Potential nucleoside transporter-mediated absorption of AICAR is not experimentally characterized."
  ],
  "decision_summary": "Prediction remains high: the most endpoint-relevant human nucleoside-analog F records support F≥20%, and L4 low-permeability analog data do not affirmatively establish F<20%. Confidence is weakened to low because the closest structural analogs show very low passive permeability and no AICAR-specific PK is available."
}

